import{c as o,Q as e,j as r,m as s}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"地圖之外的疆域：支配 Workspace 自主性的 Out-of-Repo 力量","description":"","frontmatter":{"date":"2026-07-04T00:00:00.000Z","artifacts":["scripts/territory-probe.sh","research/ROUTINES-DEPLOYED.md","research/prompts/territory-blindspot-pass-prompt.md"],"grounded_sources":["list_triggers 實測（5 個 trig_*，2026-07-04）","/root/.claude/ 檔案系統實勘","/tmp/cc-workspace sparse clone 實勘","env 實測 + .claude/hooks/session-init.sh L263-313","memory/MEMORY.md · memory/LESSONS.md（07-02/07-03 事故）"],"method":"@trq212 A Field Guide to Fable: Finding Your Unknowns（research/tweets/2026-07-03-@trq212-215386.md）","scope":"workspace 之外、卻支配 workspace 自主學習/進化/Goal-Loop 的力量","type":"blindspot-pass-report"},"headers":[],"relativePath":"research/reports/2026-07-04-territory-beyond-workspace.md","filePath":"research/reports/2026-07-04-territory-beyond-workspace.md","lastUpdated":1785909234000}'),d={name:"research/reports/2026-07-04-territory-beyond-workspace.md"};function n(a,t,i,c,l,p){return e(),r("div",null,[...t[0]||(t[0]=[s(`<h1 id="地圖之外的疆域-支配-workspace-自主性的-out-of-repo-力量" tabindex="-1">地圖之外的疆域：支配 Workspace 自主性的 Out-of-Repo 力量 <a class="header-anchor" href="#地圖之外的疆域-支配-workspace-自主性的-out-of-repo-力量" aria-label="Permalink to &quot;地圖之外的疆域：支配 Workspace 自主性的 Out-of-Repo 力量&quot;">​</a></h1><blockquote><p>方法論：把 Thariq 的「map is not the territory + 四象限未知數」反向套用在 workspace 本身。 <strong>地圖</strong> = repo 內全部 CLAUDE.md / rules / skills / hooks / agents 文件。 <strong>疆域</strong> = 這些文件實際運行所在的平台。本報告只寫「不在地圖上、卻改變行為」的疆域。</p></blockquote><h2 id="執行摘要" tabindex="-1">執行摘要 <a class="header-anchor" href="#執行摘要" aria-label="Permalink to &quot;執行摘要&quot;">​</a></h2><p>Workspace 的自主性（Goal 注入、Loop 執行、自我進化、模型調用）實際由 <strong>8 層 out-of-repo 力量</strong>支配，其中 <strong>只有 2 層半有 repo 文件對應</strong>。最重要的三個發現：</p><ol><li><strong>自主性的「基因」存放在 Anthropic server-side trigger store，不在 repo</strong>。5 個 Routine 的完整可執行 prompt（含 The Loop 六階段全文、TEST bash 閘門、PR/merge 流程）以 <code>trig_*</code> 物件存於雲端；repo 只有文本副本，兩者無機械同步——07-02 貼錯事故正是此結構性風險的實現。</li><li><strong>「當前執行模型」在檔案系統層面不可知</strong>。settings pin（<code>claude-sonnet-4-6</code>）、hook 硬編碼（<code>LATEST_KNOWN_FAMILY=claude-sonnet-5</code>）、實際 serving model（本 session <code>claude-fable-5</code>）三方不一致；<code>HARNESS_MODEL_VERSION</code> 只是 session-init 對 pin 值的 echo，<strong>不是真實模型</strong>。repo 的 pilot/model-selection 體系建立在「模型可知可控」的假設上，該假設僅在 sub-agent 參數層成立。</li><li><strong>平台注入的環境變數直接調整 Loop 行為，但 repo 從未記載</strong>：<code>CLAUDE_EFFORT=high</code>、<code>MAX_THINKING_TOKENS=31999</code>、<code>CLAUDE_AUTOCOMPACT_PCT_OVERRIDE=80</code>、<code>CLAUDE_AUTO_BACKGROUND_TASKS=true</code>——effort 檔位、思考預算、compact 觸發點、背景任務策略全部被疆域預設，而地圖（context-management.md 的 70%/30-35% compact 閾值等）渾然不覺。</li></ol><h2 id="一、疆域八層清單" tabindex="-1">一、疆域八層清單 <a class="header-anchor" href="#一、疆域八層清單" aria-label="Permalink to &quot;一、疆域八層清單&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>疆域層</th><th>位置</th><th>對自主性的影響</th><th>repo 文件化</th></tr></thead><tbody><tr><td>T1</td><td><strong>Harness system prompt</strong></td><td>Anthropic runtime（每 session 注入）</td><td>最底層 Goal 驅動：「operating autonomously、不得中途問使用者、turn 結尾不得是計畫」；Workflow（ultracode gate）、ScheduleWakeup（cache 經濟學塑形自主節奏）、Agent（背景執行+自動喚醒）、context compactor、undercover 模型身份</td><td>❌ 無</td></tr><tr><td>T2</td><td><strong>Server-side trigger store</strong></td><td>claude.ai（<code>trig_*</code> × 5）</td><td>時間驅動的 Goal 注入：Routines A–E 每日/每週自主研究-進化循環的可執行本體</td><td>⚠️ 部分（prompt 文本在 repo，排程/綁定/實際部署態在雲端）</td></tr><tr><td>T3</td><td><strong>Launcher 層</strong></td><td><code>/root/.claude/</code></td><td>repo 外的 hooks 先於 repo hooks：SessionStart 強制 git identity（noreply@anthropic.com + Co-authored-by 注入）、<strong>Stop gate 擋停未 commit/push 的 session</strong>（本 session 實際被擋停一次）；<code>.last-seen-model</code> 跨 session 模型印記；另有 2 個 dormant slackbot hooks</td><td>❌ 無</td></tr><tr><td>T4</td><td><strong>Cloud config clone</strong></td><td><code>/tmp/cc-workspace/</code></td><td><code>/root/.claude/CLAUDE.md</code> 全文只有一行 <code>@/tmp/cc-workspace/CLAUDE.md</code>——全域規則的真正來源是 session-init 從 GitHub sparse clone 的副本（TTL 3600s）；規則生效走「GitHub main → clone → @import」而非工作樹</td><td>⚠️ 部分（session-init.sh 在 repo，產物在 repo 外）</td></tr><tr><td>T5</td><td><strong>模型調用路徑</strong></td><td>平台 routing</td><td>主對話模型由平台決定（Fable5 全球回歸分類器曾靜默降級 Opus 4.8，MEMORY 07-02）；repo 可控點只有 sub-agent 的 <code>model</code>/<code>effort</code> 參數與 Workflow <code>agent()</code> opts；mid-session 不可切主模型</td><td>⚠️ 部分（pilot skills 假設可控，降級事件已入 MEMORY）</td></tr><tr><td>T6</td><td><strong>網路/身份基礎設施</strong></td><td><code>/root/.ccr/</code> + git proxy</td><td>所有 outbound HTTPS 經 agent proxy（TLS 重終結 + egress policy）；工作 repo remote 是 <code>127.0.0.1:41729</code> 本地 git 代理而非 GitHub；OAuth token 走 file descriptor（env 無 key）；限制自主網路行為的硬邊界</td><td>❌ 無（僅 /root/.ccr/README.md 平台側指引）</td></tr><tr><td>T7</td><td><strong>GitHub server-side 行為</strong></td><td>github.com</td><td>web merge = server-side 3-way，<strong>不執行 <code>.gitattributes</code> merge driver</strong> → MEMORY.md 反覆被覆蓋的根因（pr-guard G3 的敵人）；Actions ai-news-aggregator（UTC 23:00）是 Routine A 的上游輸入，失敗即斷糧</td><td>⚠️ 部分（pr-guard/Routine 文件記其症狀）</td></tr><tr><td>T8</td><td><strong>Context compactor</strong></td><td>harness</td><td>長對話自動摘要（全量 rewrite，~25% 保留）；repo 的 compact 規則只能「提示」不能控制；<code>CLAUDE_AUTOCOMPACT_PCT_OVERRIDE=80</code> 由平台注入，與 context-management.md 的 70% 建議並存但互不知情</td><td>⚠️ 部分（規則有對策，無機制文件）</td></tr></tbody></table><h2 id="二、四象限盤點-本次-blindspot-pass-的產出" tabindex="-1">二、四象限盤點（本次 blindspot pass 的產出） <a class="header-anchor" href="#二、四象限盤點-本次-blindspot-pass-的產出" aria-label="Permalink to &quot;二、四象限盤點（本次 blindspot pass 的產出）&quot;">​</a></h2><h3 id="known-knowns-地圖上的" tabindex="-1">Known Knowns（地圖上的） <a class="header-anchor" href="#known-knowns-地圖上的" aria-label="Permalink to &quot;Known Knowns（地圖上的）&quot;">​</a></h3><p>The Loop 六階段、L1–L4 四層架構、hooks=唯一 mechanism、Routines 的 prompt 文本、pilot 檔位體系。</p><h3 id="known-unknowns-已知待決-memory-有記錄" tabindex="-1">Known Unknowns（已知待決，MEMORY 有記錄） <a class="header-anchor" href="#known-unknowns-已知待決-memory-有記錄" aria-label="Permalink to &quot;Known Unknowns（已知待決，MEMORY 有記錄）&quot;">​</a></h3><ul><li>待辦#6：model pin 是否更新為 claude-sonnet-5（使用者跨 session 決策）。</li><li>待辦#7：Opus 4.8 靜默導流是否消耗 Fable 額度（需 <code>/usage</code> 親測）。</li><li>autoDream hook 模擬的 server-side 功能正式 GA 後是否與 dreaming-consolidator 雙跑衝突。</li></ul><h3 id="unknown-knowns-一直在生效、卻沒人寫下來的" tabindex="-1">Unknown Knowns（一直在生效、卻沒人寫下來的） <a class="header-anchor" href="#unknown-knowns-一直在生效、卻沒人寫下來的" aria-label="Permalink to &quot;Unknown Knowns（一直在生效、卻沒人寫下來的）&quot;">​</a></h3><ul><li><strong>Launcher Stop gate</strong>：每個 session 的「必 commit+push」紀律其實不是 core.md 的功勞，是 <code>/root/.claude/stop-hook-git-check.sh</code> 以 exit 2 硬擋——repo 把它當自身文化，實為疆域強制。</li><li><strong><code>HARNESS_MODEL_VERSION</code> 是 pin echo 不是真實模型</strong>：diff-size-guard 等以它選 per-model 門檻，實際上讀的是 settings 靜態值；模型換代/降級時門檻直接用錯。</li><li><strong>git 身份與 provenance</strong>：commit 作者、Co-authored-by、Claude-Session URL 全由 launcher 層決定格式——workspace 學習資料（git 歷史）的來源標記不歸 workspace 管。</li></ul><h3 id="unknown-unknowns-本次新發現" tabindex="-1">Unknown Unknowns（本次新發現） <a class="header-anchor" href="#unknown-unknowns-本次新發現" aria-label="Permalink to &quot;Unknown Unknowns（本次新發現）&quot;">​</a></h3><ol><li><strong>平台 env 直調 Loop 參數</strong>：<code>CLAUDE_EFFORT=high</code> / <code>MAX_THINKING_TOKENS=31999</code> / <code>CLAUDE_AUTOCOMPACT_PCT_OVERRIDE=80</code> / <code>CLAUDE_USAGE_LIMIT_USD=150</code>——effort-first 原則（delegation-protocol §1）其實已被平台在 env 層實作，repo 無一字提及。</li><li><strong>行為契約存在第二副本</strong>：5 個 trigger prompt 各自內嵌 The Loop 六階段全文 → core.md 改版時 trigger 內嵌版不會跟著改 = <strong>內建 silent fork</strong>（與 multi-mode-agent 內聯鏡像同構的問題，但這份在雲端、更難察覺）。</li><li><strong>四套排程器並存</strong>：CCR triggers（server-side）、CronCreate（deferred tool）、ScheduleWakeup（session 內）、GitHub Actions——只有最後一套定義在 repo；無統一健康監控。</li><li><strong>CLI 版本雙值</strong>：env <code>CLAUDE_CODE_VERSION=2.1.42</code> vs <code>AI_AGENT=claude-code_2-1-201_agent</code>，哪個生效未知。</li><li><strong>Dormant hooks</strong>：<code>stop-hook-reply-gate.py</code> + <code>user-prompt-submit-reply-reminder.py</code> 存在於 launcher 目錄但未註冊——未來被啟用時行為會無預警改變。</li></ol><h2 id="三、自主性堆疊解析-goal-loop-模型調用的真相" tabindex="-1">三、自主性堆疊解析（Goal / Loop / 模型調用的真相） <a class="header-anchor" href="#三、自主性堆疊解析-goal-loop-模型調用的真相" aria-label="Permalink to &quot;三、自主性堆疊解析（Goal / Loop / 模型調用的真相）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ G5 跨 session 學習   memory/ + dreaming + LESSONS      │ repo（policy）</span></span>
<span class="line"><span>│ G4 行為契約          CLAUDE.md + rules（The Loop）      │ repo（policy）</span></span>
<span class="line"><span>│ G3 強制機制          hooks（repo）+ launcher hooks      │ repo+疆域（mechanism）</span></span>
<span class="line"><span>│ G2 時間驅動 Goal     trigger store（Routines A–E）      │ 疆域（雲端可執行體）</span></span>
<span class="line"><span>│ G1 底層自主指令      harness system prompt              │ 疆域（不可見不可改）</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────┘</span></span></code></pre></div><ul><li><strong>Goal 從哪來</strong>：G1 的「autonomously、不得停在計畫」是所有自主行為的地基；G2 每天定時把研究 Goal 注入 fresh session；G4 的六階段只是把 G1 的原始驅動力「塑形」成可驗證流程。拿掉 repo（G4/G5），agent 仍會自主行動——只是沒有方向盤；拿掉 G1/G2，repo 寫得再好也只是靜態文本。</li><li><strong>Loop 靠什麼閉合</strong>：真正的閉環 = G2（排程喚醒）→ G4（六階段）→ G3（TEST 閘門硬擋）→ G5（RECORD 入庫）→ G2（下次喚醒讀取）。其中兩個關節在疆域：喚醒（trigger store）與擋停（launcher Stop gate）。<strong>自主進化的可靠性 = 疆域關節的可靠性</strong>，07-02 事故（trigger 貼錯 → DAILY-TOPICS 停產 2 日）證明弱點在 G2。</li><li><strong>模型調用的真相</strong>：主對話模型 = 平台 session 決定（可被分類器靜默改道）；repo 真正可控的調用點只有三處——Agent tool <code>model</code> 參數、Workflow <code>agent()</code> opts.model/effort、multi-mode-agent frontmatter。<strong>「effort 先於 model」不只是 workspace 心法，平台已用 <code>CLAUDE_EFFORT</code> env 印證同一設計</strong>。undercover mode 下模型自我認知也不可靠（Explore agent 自報 opus-4.8、實際 fable-5），故「模型驗證」必須走行為 eval（fable5-harness:calibrate 的做法正確），不能問模型自己。</li></ul><h2 id="四、依賴矩陣-repo-自主機制-×-疆域-×-失效模式-13-項精選" tabindex="-1">四、依賴矩陣（repo 自主機制 × 疆域 × 失效模式，13 項精選） <a class="header-anchor" href="#四、依賴矩陣-repo-自主機制-×-疆域-×-失效模式-13-項精選" aria-label="Permalink to &quot;四、依賴矩陣（repo 自主機制 × 疆域 × 失效模式，13 項精選）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>repo 機制</th><th>疆域依賴</th><th>失效模式</th></tr></thead><tbody><tr><td>Routines A–E prompt 文本</td><td>trigger store 部署態</td><td>貼錯/漂移（07-02 已發生）；文件 cron <code>13 3</code> vs 部署 <code>0 3</code>（07-04 已修）</td></tr><tr><td>pilot skills + settings pin</td><td>平台 model routing</td><td>靜默降級 Opus 4.8；pin ≠ 實跑模型</td></tr><tr><td>diff-size-guard per-model 門檻</td><td><code>HARNESS_MODEL_VERSION</code>（pin echo）</td><td>模型換代時用錯門檻</td></tr><tr><td>session-init 換代偵測</td><td>硬編碼 <code>LATEST_KNOWN_FAMILY</code></td><td>平台推新世代 → 永久誤報/漏報</td></tr><tr><td>RECORD / MEMORY 連續性</td><td>harness compactor + GitHub 3-way merge</td><td>約束丟失（~25% 保留）；MEMORY 被覆蓋</td></tr><tr><td><code>/loop</code>、multi-mode 排程</td><td>CronCreate/ScheduleWakeup 工具存在性</td><td>web session 無工具 → 假裝排程成功（multi-mode G3 已補 policy 防呆）</td></tr><tr><td>sub-agent 委派</td><td>task-notification 機制</td><td>fallback 喚醒重做不可逆操作（LESSONS L58）</td></tr><tr><td>Routine A 選題</td><td>GitHub Actions 產出</td><td>Actions 失敗 → 靜默斷糧</td></tr><tr><td>handoff 佇列</td><td>ephemeral container</td><td>gitignored 檔在 fresh clone 消失（LESSONS L84）</td></tr><tr><td>Stop 時 commit 紀律</td><td>launcher stop-hook</td><td>launcher 改版 → 紀律無聲消失</td></tr><tr><td>全域規則載入</td><td>/tmp clone TTL 3600s</td><td>main 推新規則後 1h 內 session 仍用舊版</td></tr><tr><td>網路研究（WebFetch/Search）</td><td>agent proxy egress policy</td><td>403/407 阻擋；gRPC/WS 不可用</td></tr><tr><td>unverified_success 閘門</td><td>（設計正確的反例）它假設疆域不可信</td><td>——此閘門是全 repo 對疆域姿態最正確的一條</td></tr></tbody></table><h2 id="五、演化候選-依-workspace-安全邊界分級" tabindex="-1">五、演化候選（依 workspace 安全邊界分級） <a class="header-anchor" href="#五、演化候選-依-workspace-安全邊界分級" aria-label="Permalink to &quot;五、演化候選（依 workspace 安全邊界分級）&quot;">​</a></h2><ul><li><strong>P0（research/scripts 範圍，本次已執行）</strong><ol><li><code>scripts/territory-probe.sh</code>：把本報告的疆域檢查機械化（env 注入值、三方模型值、launcher hooks、/tmp clone 新鮮度、remote 拓撲、排程器盤點），可重複執行、輸出 ✅/⚠️/❌。<strong>policy → mechanism</strong>。</li><li><code>research/ROUTINES-DEPLOYED.md</code>：trigger store 部署態鏡像（id/cron/env/created_at），給未來 session 一個「地圖 vs 疆域」diff 基準；含覆核程序。</li></ol></li><li><strong>P1（提案，<code>.claude/</code> 範圍 → 待人工審核，已入 EVOLUTION-QUEUE）</strong> 3. <code>LATEST_KNOWN_FAMILY</code> 從 session-init.sh 硬編碼改讀 SSoT 檔（如 <code>.claude/refs/model-selection-grid.md</code> frontmatter），換代只改一處。 4. healthcheck 掛載 territory-probe（coupling 巡檢項），讓疆域漂移進入 PGE 常規檢查。</li><li><strong>P2（觀察）</strong> 5. trigger prompt 內嵌 The Loop 全文的 silent fork：等 core.md 下次改版時驗證漂移代價，再決定是否改為「引用 repo 檔案」而非內嵌。 6. autoDream vs 平台 auto-dream GA 的衝突預案。</li></ul><h2 id="六、open-questions-承兩路探勘-未解" tabindex="-1">六、Open Questions（承兩路探勘，未解） <a class="header-anchor" href="#六、open-questions-承兩路探勘-未解" aria-label="Permalink to &quot;六、Open Questions（承兩路探勘，未解）&quot;">​</a></h2><ol><li>有無 API 可讓 hook 讀回<strong>真實 serving model id</strong>（而非 pin）？目前唯一可靠路徑是行為 eval。</li><li>Opus 4.8 導流的額度歸屬（待辦#7）。</li><li><code>CLAUDE_CODE_VERSION</code> 2.1.42 vs 2.1.201 何者生效。</li><li>dormant slackbot hooks 的啟用計畫。</li><li>git local_proxy（41729）與 egress proxy 的關係。</li></ol><h2 id="產物索引" tabindex="-1">產物索引 <a class="header-anchor" href="#產物索引" aria-label="Permalink to &quot;產物索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>產物</th><th>路徑</th><th>用途</th></tr></thead><tbody><tr><td>本報告</td><td><code>research/reports/2026-07-04-territory-beyond-workspace.md</code></td><td>疆域地圖 + 四象限盤點</td></tr><tr><td>疆域探測器</td><td><code>scripts/territory-probe.sh</code></td><td>機械化疆域檢查（可掛 healthcheck）</td></tr><tr><td>部署鏡像</td><td><code>research/ROUTINES-DEPLOYED.md</code></td><td>trigger store 快照 + 覆核程序</td></tr><tr><td>可攜 prompt</td><td><code>research/prompts/territory-blindspot-pass-prompt.md</code></td><td>模型無關（Claude/ChatGPT 皆可用）的四象限疆域盲點掃描 prompt</td></tr></tbody></table><h2 id="如何重複這次掃描-任何未來-session-任何模型" tabindex="-1">如何重複這次掃描（任何未來 session / 任何模型） <a class="header-anchor" href="#如何重複這次掃描-任何未來-session-任何模型" aria-label="Permalink to &quot;如何重複這次掃描（任何未來 session / 任何模型）&quot;">​</a></h2><ol><li>機械層：<code>bash scripts/territory-probe.sh</code>（秒級，✅/⚠️/❌ 輸出；⚠️ 為結構性事實不必歸零，❌ 必處理）。</li><li>排程層：session 內跑 <code>list_triggers</code>，與 <code>research/ROUTINES-DEPLOYED.md</code> 逐欄 diff；漂移即按 ROUTINES-SETUP FAQ 處置並更新快照。</li><li>認知層：把 <code>research/prompts/territory-blindspot-pass-prompt.md</code> 貼給任何 agent（含非 Claude），重做一次四象限盤點——疆域會隨平台改版而變，本報告是 2026-07-04 的快照，不是恆真清單（規則 = decaying cache 原則同樣適用於疆域地圖）。</li></ol>`,29)])])}const u=o(d,[["render",n]]);export{g as __pageData,u as default};
